        [18773] = {"邪恶力量", "使你的虚空行者、魅魔、地狱猎手和恶魔卫士的近战攻击以及小鬼的火弩箭造成的伤害提高 20%。", "EpochHead"},
        [18821] = {"强化奴役恶魔", "使你的奴役恶魔法术的攻击速度和施法速度减值降低 5%，并降低抵抗几率 5%。", "EpochHead"},
        [18822] = {"强化奴役恶魔", "使你的奴役恶魔法术的攻击速度和施法速度减值降低 10%，并降低抵抗几率 10%。", "EpochHead"},
        [84701] = {"恶魔赋能", "赋予术士召唤的恶魔赋能。\n\n小鬼：你的小鬼的火弩箭有 100% 的几率造成爆击并且 8 秒内不消耗法力。\n\n虚空行者：召唤恶魔镀层到你的虚空行者身上，使其护甲提高 15%，并提高其威胁生成能力 10%。持续8秒。\n\n魅魔：你的魅魔施展部分隐形，导致对其进行的所有近战和远程攻击有 75% 的几率落空，伤害提高 10%。\n\n地狱猎手：牺牲你最大生命值的 10% 到 20% 来强化你的地狱猎手的法术锁定能力，使其冷却时间减少 10 秒，持续 20 秒。生命值必须高于 20% 才能施放。\n\n恶魔卫士：你的恶魔卫士向目标投掷武器并激怒，使目标昏迷 4 秒，并使其造成的伤害提高 15%，持续 10 秒。\n\n地狱火：你的地狱火在 6 秒内免疫所有攻击和法术。\n\n末日卫士：你的末日卫士施放暗影箭齐射，对 30 码内所有附近的敌人造成 1016 点暗影伤害。\n\n被奴役的恶魔：对你的被奴役的恶魔施加恶魔狂怒，使其每2秒受到344点伤害，并提高其攻击速度20%和施法速度10%，持续10秒。", "EpochHead"},
        [18767] = {"魔术师大师", "减少召唤石的施法时间 0.5 秒。火石和火石效果的额外火焰伤害提高 15%。法术石现在在使用时还会提供吸收效果。使你通过灵魂石复活获得的生命值增加 10%，每当队伍成员消耗生命石时，你就会获得治疗量的 5%。", "EpochHead"},
        [18768] = {"魔术师大师", "召唤石的施法时间减少1秒。火石和火石效果的额外火焰伤害增加 30%。法术石现在在使用时还会提供吸收效果。使你通过灵魂石复活获得的生命值增加 20%，每当队伍成员消耗生命石时，你就会获得治疗量的 10%。", "EpochHead"},
        [30326] = {"法力供给", "当你通过汲取法力或生命分流法术获得法力时，你的宠物将获得你所获得法力的 33%。", "EpochHead"},
        [30327] = {"法力供给", "当你通过汲取法力或生命分流法术获得法力时，你的宠物将获得你获得的法力的 66%。", "EpochHead"},
        [30328] = {"法力供给", "当你通过汲取法力或生命分流法术获得法力时，你的宠物将获得你获得的法力的 100%。", "EpochHead"},
        [23785] = {"恶魔学家大师", "只要恶魔处于活动状态，术士和召唤的恶魔都会获得效果。\n\nImp - 减少 4% 造成的威胁。\n\n虚空行者 - 减少 2% 受到的物理伤害。\n\n魅魔 - 造成的所有伤害提高 2%。\n\n地狱猎手 - 每升一级，所有抗性增加 0.2。\n\n恶魔卫士 - 每升一级，造成的所有伤害提高 1%，所有抗性提高 0.1。", "EpochHead"},
        [23822] = {"恶魔学家大师", "只要恶魔处于活动状态，术士和召唤的恶魔都会获得效果。\n\nImp - 减少 8% 造成的威胁。\n\n虚空行者 - 减少 4% 受到的物理伤害。\n\n魅魔 - 造成的所有伤害提高 4%。\n\n地狱猎手 - 每升一级，所有抗性增加 0.4。\n\n恶魔卫士 - 每升一级，造成的所有伤害提高 2%，所有抗性提高 0.2。", "EpochHead"},
        [23823] = {"恶魔学家大师", "只要恶魔处于活动状态，术士和召唤的恶魔都会获得效果。\n\nImp - 减少 12% 造成的威胁。\n\n虚空行者 - 减少 6% 受到的物理伤害。\n\n魅魔 - 造成的所有伤害提高 6%。\n\n地狱猎手 - 每升一级，所有抗性增加 0.6。\n\n恶魔卫士 - 每升一级，造成的所有伤害提高 3%，所有抗性提高 0.3。", "EpochHead"},
        [23824] = {"恶魔学家大师", "只要恶魔处于活动状态，术士和召唤的恶魔都会获得效果。\n\nImp - 减少 16% 造成的威胁。\n\n虚空行者 - 减少 8% 受到的物理伤害。\n\n魅魔 - 造成的所有伤害提高 8%。\n\n地狱猎手 - 每升一级，所有抗性增加 0.8。\n\n恶魔卫士 - 每升一级，造成的所有伤害提高 4%，所有抗性提高 0.4。", "EpochHead"},
        [23825] = {"恶魔学家大师", "只要恶魔处于活动状态，术士和召唤的恶魔都会获得效果。\n\nImp - 减少 20% 造成的威胁。\n\n虚空行者 - 减少 10% 受到的物理伤害。\n\n魅魔 - 造成的所有伤害提高 10%。\n\n地狱猎手 - 每升一级，所有抗性增加 1 点。\n\n恶魔卫士 - 每升一级，造成的所有伤害提高 5%，所有抗性提高 0.5。", "EpochHead"},
