        [17007] = {"狼群首领", "当处于猫、熊或巨熊形态时，狼群首领将 45 码内所有小队和团队成员的远程和近战爆击率提高 2%。 此外，你自己的近战爆击率额外增加 3%。", "EpochHead"},
