        [18562] = {"迅捷治愈", "对友方目标消耗回春或愈合效果，立即为其治疗 12 秒。回春术或 18 秒。的再生。", "EpochHead"},
        [33881] = {"自然完美", "你所有法术的爆击几率增加 1%，对你的爆击会给你自然完美效果，使你受到的所有伤害减少 2%。 最多可叠加 3 次。 持续8秒。", "EpochHead"},
        [33882] = {"自然完美", "你的所有法术的爆击几率增加 2%，对你的爆击会给你自然完美效果，使你受到的所有伤害减少 3%。 最多可叠加 3 次。 持续8秒。", "EpochHead"},
        [33883] = {"自然完美", "你的所有法术的爆击几率增加 3%，对你的爆击会给你带来自然完美效果，使你受到的所有伤害减少 4%。 最多可叠加 3 次。 持续8秒。", "EpochHead"},
