        [33891] = {"生命之树", "变形为生命之树。 在这种形态下，你为45码内的所有小队成员增加了总精神值25%的治疗效果，你的移动速度降低了20%，并且你只能施展迅捷治愈、激活、自然迅捷、树皮术、非治疗性恢复法术和持续治疗法术，但这些法术的法力消耗降低了20%。\n\n变形可以使施法者摆脱变形和移动限制效果。", "EpochHead"},

        -- --------------------------------------------------------
        -- 专业技能总览（Profession Overview Spells）
        -- 对应玩家法术书「专业」页签中的主技能法术 ID
        -- 注：Epoch 对各专业专属加成进行了大幅改版
        -- --------------------------------------------------------
        -- 炼金术 Alchemy (spell 2259)
        [2259] = {"炼金术", "药剂专精（Mixology）：你饮用的合剂与药剂，持续时间延长 100%，效果提升 25%。\n贤者之石：可升级可佩戴饰品，佩戴时强化药水治疗效果。\n全新配方：近战/远程攻强合剂，声望药剂等。", "Epoch"},
        -- 锻造 Blacksmithing (spell 2018)
        [2018] = {"锻造", "全员修理（Full Repair）：瞬间修复全身装备耐久度，提供 8 小时与 4 小时冷却两档。\n腰带扣（Belt Buckle）：白银、铁质、秘银、奥金四品级，为腰带提供永久全属性附魔。\n全新配方：坦克专用武器、投掷武器、护甲套装及珠宝饰品。", "Epoch"},
        -- 烹饪 Cooking (spell 2550)
        [2550] = {"烹饪", "全新食谱：黑咖啡、多汁熊肉汉堡，以及骨粉料理、熟熔火头骨鱼、克雷斯特福螃蟹塔可等特色美食，提供饱腹感与属性增益。", "Epoch"},
        -- 附魔 Enchanting (spell 7411)
        [7411] = {"附魔", "戒指专属附魔（五个品级）：法术强度/攻击强度/耐力，只能附魔自己的戒指。\n碎片转化：小型魔光碎片→大型魔光碎片，20 小时公共冷却。\n可制作金属法杖，以及散落世界各地的全新配方。", "Epoch"},
        -- 工程学 Engineering (spell 4036)
        [4036] = {"工程学", "强势专业，无额外属性加成（为平衡各专业热门程度）。保留全部经典旧世工程玩具。\n地精工程（Goblin Engineering）vs 侏儒工程（Gnome Engineering）：两大分支各有新奇玩具。", "Epoch"},
        -- 钓鱼 Fishing (spell 7620)
        [7620] = {"钓鱼", "经典旧世区域钓鱼复刻，全新渔具箱。熔岩水域可垂钓（需特殊鱼竿）。\n开服即可接受钓鱼日常任务，可获得垂钓老手（Salty）荣誉称号。", "Epoch"},
        -- 急救 First Aid (spell 3273)
        [3273] = {"急救", "完全还原 1.12 旧世原版急救，含分流治疗（Triage）任务。绷带治疗量因 TBC 耐力倍率提升而上调。\n急救材料纳入任务所需道具，全新交易市场。", "Epoch"},
        -- 采药 Herbalism (spell 2366)
        [2366] = {"采药", "自然天赋（Natural Affinity）：全法术系抗性提升，随采药等级增长。\n莲花亲和（Lotus Affinity）：采集高阶草药时有几率额外附赠黑莲花。\n野蛮萃取（Savage Harvest）：野外生物死亡后可对尸体搜刮额外资源。", "Epoch"},
        -- 制皮 Leatherworking (spell 2108)
        [2108] = {"制皮", "护甲片：临时附魔于护腕，法术强度/攻击强度/耐力三种类型。\n疾行加持：专属坐骑鞍具，满级最多提升 5% 移动速度；新制皮专业背包。\n龙鳞与元素专精：所有分支均有新配方。", "Epoch"},
        -- 采矿 Mining (spell 2575)
        [2575] = {"采矿", "钢铁体魄（Toughness）：总耐力属性加成，随采矿等级提升增加。\n奥金矿脉：测试阶段，需更多精力开采，产出物价值超高。\n凶蛮采掘（Savage Mining）：野外生物死后可进行尸体采矿，额外获取资源。", "Epoch"},
        -- 剥皮 Skinning (spell 8613)
        [8613] = {"剥皮", "野性猎手（Savage Hunter）：对野兽和龙类造成的伤害提升，随剥皮等级成长。\n大量配方纳入稀有毛皮，提供多元经济来源。升级途中顺便剥皮，轻松赚取金币。", "Epoch"},
        -- 裁缝 Tailoring (spell 3908)
        [3908] = {"裁缝", "披风刺绣（五个品级）：法术强度/攻击强度/耐力，只能附魔自己的披风。\n布料搜寻（Cloth Scavenging）：击杀人型怪物额外获取布料。\n全新及重做配方：大量新配方，重做月布系列经典装备。", "Epoch"},

        -- --------------------------------------------------------
        -- 专业专属被动加成法术（Profession Passive Bonus Spells）
        -- 注：Epoch 对部分专业被动进行了全面改版（使用已知法术 ID）
        -- --------------------------------------------------------
        -- 炼金术：药剂专精 Mixology (WotLK spell 53042)
        [53042] = {"药剂专精", "你饮用的合剂与药剂，持续时间延长 100%，效果提升 25%。", "Epoch"},
        -- 采矿：钢铁体魄 Toughness (WotLK spell 53120, Epoch: total stamina bonus)
        [53120] = {"钢铁体魄", "你的总耐力属性随采矿技能等级的提升而增加。", "Epoch"},
        -- 剥皮：野性猎手 Savage Hunter (WotLK spell 53526, Epoch: damage vs beasts/dragonkin)
        [53526] = {"野性猎手", "对野兽和龙类造成的伤害随剥皮技能等级的提升而增加。", "Epoch"},
        -- 采药：自然天赋 Natural Affinity (WotLK spell 55503, Epoch: all-school resistance)
        [55503] = {"自然天赋", "你对所有法术系魔法的抗性随采药技能等级的提升而增加。", "Epoch"},
        -- 裁缝：布料搜寻 Cloth Scavenging (WotLK spell 56470)
        [56470] = {"布料搜寻", "击杀人型怪物时，额外获取更多布料。", "Epoch"},
    }
end
